import{_ as t,l as i,o as e,c as s,v as o,p as n,x as P,d as c,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"coNP 与多项式层级","description":"","frontmatter":{"title":"coNP 与多项式层级","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/conp-polynomial-hierarchy.md","filePath":"cs/conp-polynomial-hierarchy.md","lastUpdated":1789023840000}'),N={name:"cs/conp-polynomial-hierarchy.md"};function h(m,a,d,_,S,u){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="conp-与多项式层级" tabindex="-1">coNP 与多项式层级 <a class="header-anchor" href="#conp-与多项式层级" aria-label="Permalink to &quot;coNP 与多项式层级&quot;">​</a></h1><div class="epigraph"><p>coNP 是 NP 语言的补；多项式层级用交替的多项式长量词给 NP、coNP 搭楼，PH 落在 PSPACE 里。</p><footer>—— 据 Stockmeyer；Garey and Johnson；Arora and Barak 整理</footer></div><p>上一课<a href="/cs/cook-levin">Cook–Levin</a> 把 NP 钉在「存在短证书」。缺口是<strong>否实例</strong>的短证，以及更多量词。coNP：\\(\\overline L\\in\\mathrm{NP}\\)。TAUTOLOGY、UNSAT 是 coNP 完全候选。多项式层级 \\(\\Sigma_k^p,\\Pi_k^p\\)：交替 \\(\\exists\\forall\\) 各多项式长。\\(\\mathrm{NP}=\\Sigma_1^p\\)，\\(\\mathrm{coNP}=\\Pi_1^p\\)。\\(\\mathrm{PH}\\subseteq\\mathrm{PSPACE}\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「无哈密顿回路」不像有短 Yes 证书。若 \\(NP=\\mathrm{coNP}\\)，层级会塌。若任一 \\(\\Sigma_k^p\\) 完全问题落到下一层，PH 塌缩。本课不裁决塌缩，只给量词形状。\\(\\Pi_2\\) 例：\\(\\forall\\) 对手策略 \\(\\exists\\) 我的应对（某些博弈的短局）。TQBF 不限制量词个数，故在 PSPACE 而不必在 PH 的固定层。</p><p>主干只谈 \\(P\\) vs \\(NP\\)。本课把第三轴 coNP 插上，避免把「难」全写成 NPC。</p><h3 id="conp-不是「补算法」" tabindex="-1">coNP 不是「补算法」 <a class="header-anchor" href="#conp-不是「补算法」" aria-label="Permalink to &quot;coNP 不是「补算法」&quot;">​</a></h3><p>\\(P\\) 对补封闭：把是/否翻转。NP 未知。证书对 Yes 短，不自动给 No 短证。UNSAT 的短证若存在且易验，则 \\(NP=\\mathrm{coNP}\\) 一类结论，未被证明。</p><p><span class="marginnote">Stockmeyer 的多项式层级。Garey–Johnson 讨论 coNP。Arora–Barak 第 5 章。本课不引入预言机塌缩的全部相对化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 \\(\\Sigma_2^p\\)：存在多项式 \\(u\\)，对所有多项式 \\(v\\)，某 P 谓词 \\(R(x,u,v)\\)。指出 PH 的完全问题（带 \\(k\\) 个量词的 3SAT 变体）点名即可。画包含图：\\(P\\subseteq NP\\cap coNP\\subseteq NP\\subseteq PH\\subseteq PSPACE\\)。</p>',11)),(e(),n(p,null,{default:P(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PCLS%5B%22P%22%5D%20--%3E%20NPC%5B%22NP%22%5D%0A%20%20PCLS%20--%3E%20CONP%5B%22coNP%22%5D%0A%20%20NPC%20--%3E%20PH%5B%22PH%20%E4%BA%A4%E6%9B%BF%E9%87%8F%E8%AF%8D%22%5D%0A%20%20CONP%20--%3E%20PH%0A%20%20PH%20--%3E%20PSP%5B%22PSPACE%22%5D%0A"})]),fallback:P(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>量词个数对应交替图灵机的交替次数。Savitch 把空间非确定平方掉，管不到量词交替的时间类。若 \\(P=NP\\) 则 PH \\(=P\\)。故「只证了 NP 完全」之后，层级问题仍然在。</p><p>不要把 coNP 完全当成「比 NPC 更难」：它们是不同方向的完全，未知谁包含谁。</p><p>若 \\(NP=\\mathrm{coNP}\\)，则 PH 塌到第二层以下（实际上到 \\(NP\\)）。\\(\\Sigma_2\\) 完全问题的脸谱是「存在电路使某 SAT 公式恰有某种计数性质」一类，本课不列清单。交替图灵机的交替次数对应层数；PSPACE 允许多项式次交替，故 TQBF 不必停在固定 \\(k\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Toda 定理，不引入 \\(\\mathrm{PH}\\subseteq P^{\\#P}\\)。不把 \\(\\Sigma_2\\) 电路下界提前。后课默认：Yes 短证是 NP，No 短证是 coNP；更多交替是 PH。下一课硬币：BPP。</p><p>量词个数固定的层级与 PSPACE 的「任意多项式个量词」之间仍可能有缝。\\(P=NP\\) 会把整栋 PH 压成 \\(P\\)。不要把 coNP 完全说成「比 NPC 更难」——方向不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>coNP = NP 的补类；UNSAT 是典型对象。</li><li>PH 是多项式长交替量词；\\(PH\\subseteq PSPACE\\)。</li><li>塌缩开放；\\(P=NP\\) 会把整栋楼压扁。</li><li>出处：Stockmeyer；Garey and Johnson；Arora and Barak。</li></ul>',9))])}const k=t(N,[["render",h]]);export{T as __pageData,k as default};
